// CodePen version of examples/react (JS preprocessor: Babel). Generated by scripts/build.mjs.
import React, { useCallback, useMemo, useRef, useState } from 'https://esm.sh/react@19';
import { flushSync } from 'https://esm.sh/react-dom@19';
import { createRoot } from 'https://esm.sh/react-dom@19/client';
import { distortionWave } from 'https://cdn.jsdelivr.net/npm/distortion-wave@0.2/+esm';

// distortionWave() captures the element right after your update returns, so React has to render
// synchronously: flushSync does that (same as with document.startViewTransition).
//
//   const wave = useWave({ duration: 1200 });
//   <button onClick={(e) => wave(cardRef, () => setOpen(true), { source: e.currentTarget, focus: e })}>
function useWave(defaults) {
  return useCallback((target, update, options) => {
    const el = target && 'current' in target ? target.current : target;
    if (!el) { update(); return null; }
    return distortionWave(el, () => flushSync(update), { ...defaults, ...options });
  }, [defaults]);
}

const EASINGS = ['cubic-bezier(0.2, 1, 0.3, 1)', 'ease-in-out', 'ease-out', 'linear'];
const PALETTES = ['aurora', 'ocean', 'mint', 'ember'];
const PLANS = {
  monthly: { price: '$12', per: '/ month', perks: ['3 projects', 'Community support'] },
  yearly: { price: '$120', per: '/ year', perks: ['Unlimited projects', 'Priority support', 'Early access'], save: '2 months free' },
};

function App() {
  const [settings, setSettings] = useState({ duration: 0, easing: EASINGS[0], intensity: 1, palette: 'aurora' });
  // 0 = automatic duration (from the size of each element)
  const options = useMemo(() => ({ ...settings, duration: settings.duration || undefined }), [settings]);
  const wave = useWave(options);
  const [dark, setDark] = useState(true);
  const app = useRef(null);

  return (
    <div className="app" data-theme={dark ? 'dark' : 'light'} ref={app}>
      <header className="top">
        <div>
          <h1>distortion-wave + React</h1>
          <p>Every click below is a state change wrapped in <code>useWave()</code>.</p>
        </div>
        <button
          className="switch" role="switch" aria-checked={dark} aria-label="Dark theme"
          onClick={(e) => wave(app, () => setDark((d) => !d), { source: e.currentTarget, focus: e })}
        />
      </header>
      <main className="grid">
        <Like wave={wave} />
        <Pricing wave={wave} />
        <Todos wave={wave} />
        <Settings value={settings} onChange={setSettings} />
      </main>
    </div>
  );
}

function Like({ wave }) {
  const [liked, setLiked] = useState(false);
  const ref = useRef(null);
  return (
    <section className="cell">
      <h2>Like</h2>
      <button ref={ref} className="like" aria-pressed={liked} onClick={(e) => wave(ref, () => setLiked((v) => !v), { focus: e })}>
        <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.6-7 10-7 10z" /></svg>
        <span>{liked ? 129 : 128}</span>
      </button>
    </section>
  );
}

function Pricing({ wave }) {
  const [plan, setPlan] = useState('monthly');
  const panel = useRef(null);
  const p = PLANS[plan];
  return (
    <section className="cell">
      <h2>Pricing</h2>
      <div className="segmented" role="tablist">
        {Object.keys(PLANS).map((key) => (
          <button
            key={key} role="tab" aria-selected={plan === key}
            onClick={(e) => plan !== key && wave(panel, () => setPlan(key), { source: e.currentTarget, focus: e })}
          >
            {key === 'monthly' ? 'Monthly' : 'Yearly'}
          </button>
        ))}
      </div>
      <div className="plan" ref={panel}>
        <div className="amount">{p.price} <small>{p.per}</small></div>
        {p.save && <span className="save">{p.save}</span>}
        <ul>{p.perks.map((x) => <li key={x}>{x}</li>)}</ul>
      </div>
    </section>
  );
}

function Todos({ wave }) {
  const [items, setItems] = useState([{ id: 1, text: 'Publish on npm', done: true }, { id: 2, text: 'Write the React example', done: false }]);
  const [text, setText] = useState('Ship it');
  const list = useRef(null);
  const add = useRef(null);
  const toggle = (id) => setItems((xs) => xs.map((x) => (x.id === id ? { ...x, done: !x.done } : x)));
  return (
    <section className="cell">
      <h2>Todos</h2>
      <ul className="todos" ref={list}>
        {items.map((it) => <Todo key={it.id} item={it} wave={wave} onToggle={() => toggle(it.id)} />)}
      </ul>
      <form
        className="add"
        onSubmit={(e) => {
          e.preventDefault();
          if (!text.trim()) return;
          // the list grows: the outline of the wave follows the new height
          wave(list, () => { setItems((xs) => [...xs, { id: Date.now(), text, done: false }].slice(-5)); setText(''); }, { source: add.current });
        }}
      >
        <input value={text} onChange={(e) => setText(e.target.value)} aria-label="New todo" />
        <button ref={add} className="btn">Add</button>
      </form>
    </section>
  );
}

function Todo({ item, wave, onToggle }) {
  const ref = useRef(null);
  return (
    <li>
      <button ref={ref} className="todo" aria-pressed={item.done} onClick={(e) => wave(ref, onToggle, { focus: e })}>
        <i />{item.text}
      </button>
    </li>
  );
}

function Settings({ value, onChange }) {
  const set = (k) => (e) => onChange({ ...value, [k]: e.target.type === 'range' ? Number(e.target.value) : e.target.value });
  const code = Object.entries({ ...value, duration: value.duration || undefined })
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => `${k}: ${typeof v === 'string' ? `'${v}'` : v}`)
    .join(', ');
  return (
    <section className="cell settings">
      <h2>Options</h2>
      <label>Duration <output>{value.duration ? `${value.duration} ms` : 'auto'}</output>
        <input type="range" min="0" max="4000" step="100" value={value.duration} onChange={set('duration')} />
      </label>
      <label>Intensity <output>{value.intensity.toFixed(1)}</output>
        <input type="range" min="0" max="2" step="0.1" value={value.intensity} onChange={set('intensity')} />
      </label>
      <label>Easing
        <select value={value.easing} onChange={set('easing')}>{EASINGS.map((x) => <option key={x}>{x}</option>)}</select>
      </label>
      <label>Palette
        <select value={value.palette} onChange={set('palette')}>{PALETTES.map((x) => <option key={x}>{x}</option>)}</select>
      </label>
      <pre><code>useWave({'{ '}{code}{' }'})</code></pre>
    </section>
  );
}

createRoot(document.getElementById('root')).render(<App />);
